#!/usr/bin/env python3
"""One-time integrity upgrade for ketogenicresearch.

This script is intentionally idempotent. It installs the corrected source-integrity
pipeline, consolidates active GitHub workflows, quarantines the two known contaminated
article drafts, repairs local metadata, fixes Library filters/counters, and rebuilds
static derived pages without making external network requests.
"""
from __future__ import annotations

import base64
import json
import os
import re
import shutil
import subprocess
import sys
import zlib
from datetime import datetime, timezone
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]

BLOBS = {
  "scripts/update_latest.py": "",
  "scripts/generate_articles.py": "",
  "scripts/audit_article_sources.py": "",
  "scripts/sync_publication_counters.py": "",
  "scripts/promote_auto.py": "",
  "scripts/promote_auto_v5.py": "",
  "scripts/library_v5.py": "",
  "scripts/render_articles.py": "",
  "scripts/build_evidence_trends.py": "",
  "script.js": "",
  ".github/workflows/update-literature.yml": "",
  ".github/workflows/generate-articles-auto.yml": "",
  ".github/workflows/expand-scientific-library.yml": "",
  ".github/workflows/synchronize-publication-counters.yml": "",
  ".github/workflows/repair-article-source-integrity.yml": ""
}

KEEP_WORKFLOWS = {
    'update-literature.yml',
    'generate-articles-auto.yml',
    'expand-scientific-library.yml',
    'build-evidence-trends.yml',
    'backfill-publication-years.yml',
    'repair-fulltext-links.yml',
    'synchronize-publication-counters.yml',
    'repair-article-source-integrity.yml',
    # keep this installer visible so the upgrade can be safely re-run if needed
    'apply-integrity-upgrade.yml',
}

BAD_PMIDS = {
    '42709766': {
        'doi': '10.1371/journal.pone.0357797',
        'pmc': '',
        'evidence_type': 'Preclinical / mechanistic',
        'evidence_type_it': 'Preclinico / meccanicistico',
        'reason': 'Stored DOI/PMCID did not belong to this PubMed record.',
    },
    '42760380': {
        'doi': '10.1038/s41430-026-01821-3',
        'pmc': '',
        'evidence_type': 'Case report / case series',
        'evidence_type_it': 'Case report / case series',
        'reason': 'Stored DOI/PMCID/full-text source did not belong to this PubMed record.',
    },
}

ANIMAL_WORDS = re.compile(
    r'\b(mice|mouse|murine|rats?|rat|zebrafish|swine|piglets?|rabbits?|canine|feline)\b',
    re.I,
)


def write_payloads() -> None:
    for rel, enc in BLOBS.items():
        path = ROOT / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        raw = zlib.decompress(base64.b64decode(enc))
        path.write_bytes(raw)
        if path.suffix == '.py':
            compile(raw.decode('utf-8'), str(path), 'exec')
        print(f'Installed {rel}')


def archive_old_workflows() -> None:
    wfdir = ROOT / '.github' / 'workflows'
    archive = ROOT / '.github' / 'workflows-archive' / 'one-time-migrations'
    legacy = ROOT / '.github' / 'workflows-archive' / 'legacy-code'
    archive.mkdir(parents=True, exist_ok=True)
    legacy.mkdir(parents=True, exist_ok=True)

    # YAML workflows not needed for recurring operation are retained in an archive,
    # rather than deleted, so their history remains available without cluttering Actions.
    for p in list(wfdir.glob('*.yml')) + list(wfdir.glob('*.yaml')):
        if p.name not in KEEP_WORKFLOWS:
            dest = archive / p.name
            if dest.exists():
                dest.unlink()
            shutil.move(str(p), str(dest))
            print(f'Archived workflow {p.name}')

    # Stray executable code and bytecode do not belong in the workflows directory.
    for p in list(wfdir.glob('*.py')) + list(wfdir.glob('*.pyc')):
        dest = legacy / p.name
        if dest.exists():
            dest.unlink()
        shutil.move(str(p), str(dest))
        print(f'Archived workflow code {p.name}')

    scripts_sub = wfdir / 'scripts'
    if scripts_sub.exists():
        dest = legacy / 'scripts'
        if dest.exists():
            shutil.rmtree(dest)
        shutil.move(str(scripts_sub), str(dest))
        print('Archived .github/workflows/scripts')


def remove_caches() -> None:
    for d in list(ROOT.rglob('__pycache__')):
        if d.is_dir():
            shutil.rmtree(d, ignore_errors=True)
    for p in list(ROOT.rglob('*.pyc')):
        try:
            p.unlink()
        except FileNotFoundError:
            pass


def fix_library_duplicate_search() -> None:
    path = ROOT / 'library.html'
    if not path.exists():
        return
    s = path.read_text(encoding='utf-8')
    # Remove the obsolete second search control under the clinical-index heading.
    pattern = re.compile(
        r'<label class="library-search-wrap">\s*'
        r'<span[^>]*>Search folders</span>\s*'
        r'<input[^>]*id="librarySearch"[^>]*/>\s*'
        r'</label>',
        re.I | re.S,
    )
    s2, n = pattern.subn('', s, count=1)
    if n:
        path.write_text(s2, encoding='utf-8')
        print('Removed duplicate librarySearch control.')
    else:
        print('Duplicate librarySearch control already absent.')


def fix_methodology_canonical() -> None:
    path = ROOT / 'methodology.html'
    if not path.exists():
        return
    s = path.read_text(encoding='utf-8')
    # Attribute order varies across prior generated HTML, so match the complete tags.
    s = re.sub(
        r'<link\s+href=["\']https://ketogenicresearch\.org/?["\']\s+rel=["\']canonical["\']\s*/?>',
        '<link href="https://ketogenicresearch.org/methodology.html" rel="canonical"/>',
        s,
        flags=re.I,
    )
    s = re.sub(
        r'<meta\s+content=["\']https://ketogenicresearch\.org/?["\']\s+property=["\']og:url["\']\s*/?>',
        '<meta content="https://ketogenicresearch.org/methodology.html" property="og:url"/>',
        s,
        flags=re.I,
    )
    path.write_text(s, encoding='utf-8')
    print('Normalized methodology canonical URL.')


def update_record_file(filename: str) -> None:
    path = ROOT / filename
    if not path.exists():
        return
    try:
        obj = json.loads(path.read_text(encoding='utf-8'))
    except Exception as exc:
        raise SystemExit(f'Cannot parse {filename}: {exc}')

    changed = 0
    def walk(v):
        nonlocal changed
        if isinstance(v, dict):
            pmid = str(v.get('pmid', '')).strip()
            if pmid in BAD_PMIDS:
                spec = BAD_PMIDS[pmid]
                for key in ('doi', 'pmc', 'evidence_type', 'evidence_type_it'):
                    if key in v or key not in {'pmc'}:
                        if v.get(key, '') != spec[key]:
                            v[key] = spec[key]
                            changed += 1
                expected_doi_url = f"https://doi.org/{spec['doi']}" if spec['doi'] else ''
                expected_pmc_url = f"https://pmc.ncbi.nlm.nih.gov/articles/{spec['pmc']}/" if spec['pmc'] else ''
                if 'doi_url' in v and v.get('doi_url', '') != expected_doi_url:
                    v['doi_url'] = expected_doi_url
                    changed += 1
                if 'pmc_url' in v and v.get('pmc_url', '') != expected_pmc_url:
                    v['pmc_url'] = expected_pmc_url
                    changed += 1
            # Repair unambiguous animal-title false positives locally. Future records are
            # handled by the structured PubMed classifier installed by this upgrade.
            title = str(v.get('title', ''))
            ev = str(v.get('evidence_type', ''))
            if ANIMAL_WORDS.search(title) and ev in {
                'Clinical trial / intervention', 'Randomized clinical trial'
            }:
                v['evidence_type'] = 'Preclinical / mechanistic'
                if 'evidence_type_it' in v:
                    v['evidence_type_it'] = 'Preclinico / meccanicistico'
                changed += 1
            for x in v.values():
                walk(x)
        elif isinstance(v, list):
            for x in v:
                walk(x)
    walk(obj)
    if changed:
        path.write_text(json.dumps(obj, indent=2, ensure_ascii=False) + '\n', encoding='utf-8')
        print(f'Updated {filename}: {changed} field(s).')
    else:
        print(f'{filename}: no metadata correction needed.')


def quarantine_known_bad_articles() -> None:
    drafts = ROOT / 'articles-drafts'
    public = ROOT / 'articles'
    quarantine = ROOT / 'articles-quarantine'
    quarantine.mkdir(exist_ok=True)

    for pmid, spec in BAD_PMIDS.items():
        for p in list(drafts.glob(f'*{pmid}*.md')):
            dest = quarantine / p.name
            if dest.exists():
                dest.unlink()
            shutil.move(str(p), str(dest))
            print(f'Quarantined draft PMID {pmid}: {p.name}')
        for p in list(public.glob(f'*{pmid}*.html')):
            p.unlink()
            print(f'Removed contaminated public article PMID {pmid}: {p.name}')

    idx_path = drafts / 'generated-index.json'
    if idx_path.exists():
        idx = json.loads(idx_path.read_text(encoding='utf-8'))
        bad = set(BAD_PMIDS)
        idx['generated_pmids'] = [str(x) for x in idx.get('generated_pmids', []) if str(x) not in bad]
        failures = idx.setdefault('failures', [])
        existing = {(str(x.get('pmid','')), str(x.get('stage',''))) for x in failures if isinstance(x, dict)}
        now = datetime.now(timezone.utc).isoformat()
        for pmid, spec in BAD_PMIDS.items():
            if (pmid, 'source_identity_manual_audit') not in existing:
                failures.append({
                    'pmid': pmid,
                    'at': now,
                    'stage': 'source_identity_manual_audit',
                    'error': spec['reason'],
                })
        idx['failures'] = failures[-100:]
        idx['updated_at'] = now
        idx_path.write_text(json.dumps(idx, indent=2, ensure_ascii=False) + '\n', encoding='utf-8')
        print('Removed quarantined PMIDs from generated-index.json.')


def run_local(script: str) -> None:
    env = os.environ.copy()
    env['PYTHONDONTWRITEBYTECODE'] = '1'
    print(f'Running {script} ...')
    subprocess.run([sys.executable, '-B', str(ROOT / script)], cwd=ROOT, env=env, check=True)


def validate() -> None:
    # Syntax check every modified Python file without writing bytecode.
    for rel in [x for x in BLOBS if x.endswith('.py')]:
        path = ROOT / rel
        compile(path.read_text(encoding='utf-8'), str(path), 'exec')

    # Enforce one unique HTML id per root page.
    id_re = re.compile(r'\bid=["\']([^"\']+)["\']', re.I)
    dupes = []
    for p in ROOT.glob('*.html'):
        ids = id_re.findall(p.read_text(encoding='utf-8', errors='replace'))
        seen = set()
        repeated = {x for x in ids if x in seen or seen.add(x)}
        if repeated:
            dupes.append((p.name, sorted(repeated)))
    if dupes:
        raise SystemExit(f'Duplicate HTML ids remain: {dupes[:5]}')

    active_names = []
    for p in (ROOT / '.github' / 'workflows').glob('*.yml'):
        m = re.search(r'^name:\s*(.+)$', p.read_text(encoding='utf-8'), re.M)
        if m:
            active_names.append(m.group(1).strip())
    if len(active_names) != len(set(active_names)):
        raise SystemExit('Duplicate active GitHub workflow names remain.')

    print('Static integrity checks passed.')


def main() -> None:
    print('Applying Ketogenic Research integrity upgrade...')
    write_payloads()
    archive_old_workflows()
    remove_caches()
    fix_library_duplicate_search()
    fix_methodology_canonical()
    update_record_file('latest-publications.json')
    update_record_file('review-queue.json')
    quarantine_known_bad_articles()

    # Rebuild only deterministic local derivatives. The two quarantined articles are
    # regenerated later by the dedicated repair workflow, after fresh PubMed checks.
    run_local('scripts/sync_publication_counters.py')
    run_local('scripts/build_evidence_trends.py')
    run_local('scripts/render_articles.py')
    remove_caches()
    validate()

    print('INTEGRITY UPGRADE APPLIED.')
    print('Next: run Actions -> Repair article source integrity -> Run workflow.')

if __name__ == '__main__':
    main()
